def paragraphs(xml):
    return xml.findall('.//w:p',NS)

def text(p):
    return ''.join(t.text or '' for t in p.findall('.//w:t',NS))

def patch_paragraph(p,new):
    """Edit only text nodes, leaving paragraph and run properties intact."""
    nodes=p.findall('.//w:t',NS)
    old=''.join(n.text or '' for n in nodes)
    changes=[op for op in difflib.SequenceMatcher(None,old,new,autojunk=False).get_opcodes() if op[0]!='equal']
    for _,start,end,newstart,newend in reversed(changes):
        offset=0
        spans=[]
        for n in nodes:
            length=len(n.text or '')
            spans.append((n,offset,offset+length))
            offset+=length
        # Insert at the node containing the start; process backwards to keep offsets stable.
        target=next((i for i,(_,a,b) in enumerate(spans) if a<=start<b),len(spans)-1)
        insertion=new[newstart:newend]
        for i,(n,a,b) in enumerate(spans):
            value=n.text or ''
            left=max(0,min(len(value),start-a))
            right=max(0,min(len(value),end-a))
            if right>left or i==target:
                n.text=value[:left]+(insertion if i==target else '')+value[right:]
                n.set('{http://www.w3.org/XML/1998/namespace}space','preserve')
    assert text(p)==new

def correct_source():
    before_hash=hashlib.sha256(SOURCE.read_bytes()).hexdigest()
    with zipfile.ZipFile(SOURCE) as z:
        xml=etree.fromstring(z.read('word/document.xml'))
        paras=paragraphs(xml)
        before=[text(p) for p in paras]
        changes={
          32:'Фактическая база НДС составляет 960 000 руб. только при подтверждении, что доставка 30 000 руб. включена в стоимость импортируемых товаров: (10 000 USD × 93,00) + 30 000 руб. Если доставка в эту стоимость не включена, она не увеличивает базу: 10 000 USD × 93,00 = 930 000 руб. До подтверждения условия база 960 000 руб. не считается установленной.',
          33:'Итоговый ввозной НДС 22%: при подтвержденной базе 960 000 руб. — 211 200 руб.; если отдельная доставка не включена в стоимость импортируемых товаров, база 930 000 руб. и НДС 204 600 руб.',
          34:'Сумма доплаты налога зависит от подтвержденной базы. При условии ОП 202 400 руб. доплата составляет 8 800 руб. только для подтвержденной базы 960 000 руб.; для базы 930 000 руб. — 2\u00a0200 руб. До подтверждения базы сумму доплаты 8 800 руб. не считать установленной.',
          43:'Дт 68.Косвенные налоги — Кт 51 | Сумма доплаты определяется после подтверждения базы (8 800 руб. только для базы 960 000 руб. и ОП 202 400 руб.) — Доплачен остаток ввозного НДС в бюджет через ЕНП. По принятой к учету в июле поставке срок уплаты — не позднее 20 августа.',
        }
        # Consequential changes are restricted to repetitions of the disputed base and its results.
        for i in (41,48,49,78,80,84,89,92):
            value=before[i]
            value=value.replace('211 200 руб.','211 200 руб. (условно, только при подтвержденной базе 960 000 руб.)')
            value=value.replace('211 200 -','211 200 (условно) -')
            value=value.replace('8 800 руб.','8 800 руб. (условно, до подтверждения базы не считается установленной суммой)')
            if i==48:
                value=value.replace('Добавляем транспортные расходы (30 000 руб.).','Транспортные расходы 30 000 руб. увеличивают базу только при подтвержденном включении в стоимость импортируемых товаров; иначе не добавляем их в базу НДС.')
            changes[i]=value
        for i,new in changes.items(): patch_paragraph(paras[i],new)
        after=[text(p) for p in paras]
        changed=[i for i in range(len(before)) if before[i]!=after[i]]
        assert changed==sorted(changes),changed
        target=DOCS/'00_Сценарий_интенсива_с_указанными_правками.docx'
        with zipfile.ZipFile(target,'w') as output:
            for part in z.infolist():
                data=etree.tostring(xml,xml_declaration=True,encoding='UTF-8',standalone=True) if part.filename=='word/document.xml' else z.read(part.filename)
                output.writestr(part,data)
    assert hashlib.sha256(SOURCE.read_bytes()).hexdigest()==before_hash
    (OUT/'change-log.json').write_text(json.dumps({'source_sha256':before_hash,'source_unchanged':True,'paragraph_count':len(before),'changed_paragraphs':changed,'changes':[{'paragraph':i,'before':before[i],'after':after[i]} for i in changed]},ensure_ascii=False,indent=2),encoding='utf-8')
    (OUT/'corrected-extracted.txt').write_text('\n'.join(f'{i}: {t}' for i,t in enumerate(after)),encoding='utf-8')
    return target

def new_document(title):
    d=Document()
    s=d.sections[0]
    s.page_width=Inches(8.5);s.page_height=Inches(11)
    s.top_margin=s.bottom_margin=Inches(.7)
    s.left_margin=s.right_margin=Inches(.8)
    for name in ('Normal','Title','Heading 1','Heading 2'):
        style=d.styles[name]
        style.font.name='Arial';style.font.color.rgb=RGBColor(0,0,0)
        for border in style.element.findall('.//w:pBdr',NS):
            border.getparent().remove(border)
    normal=d.styles['Normal'];normal.font.size=Pt(11)
    normal.paragraph_format.space_after=Pt(5)
    normal.paragraph_format.line_spacing=1.05
    normal.paragraph_format.keep_together=True
    d.styles['Title'].font.size=Pt(19)
    d.styles['Heading 1'].font.size=Pt(14)
    d.styles['Heading 2'].font.size=Pt(12)
    d.add_paragraph(title,'Title')
    return d

def step(d,title,action,speech,check):
    d.add_paragraph(title,'Heading 2')
    d.add_paragraph('На экране. '+action).paragraph_format.keep_with_next=True
    d.add_paragraph('Озвучка. '+speech).paragraph_format.keep_with_next=True
    d.add_paragraph('Контроль. '+check)

